BEGIN;
CREATE TABLE public.program_subscription_enrollments(user_id uuid NOT NULL REFERENCES auth.users(id),edition_id uuid NOT NULL REFERENCES public.program_editions(id),program_id uuid NOT NULL REFERENCES public.trainer_programs(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,edition_id));
ALTER TABLE public.program_subscription_enrollments ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.program_subscription_enrollments FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.program_subscription_enrollments TO service_role;
GRANT SELECT ON public.program_subscription_enrollments TO authenticated;
CREATE POLICY own_program_subscription ON public.program_subscription_enrollments FOR SELECT TO authenticated USING(user_id=auth.uid());
ALTER FUNCTION public.program_validate(jsonb,uuid,boolean) RENAME TO program_validate_v62;
CREATE FUNCTION public.program_validate(p_data jsonb,p_trainer uuid,p_allow_empty boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE doc jsonb:=p_data;BEGIN IF p_data ? 'subscription_access' AND jsonb_typeof(p_data->'subscription_access')<>'boolean' THEN RAISE EXCEPTION 'Invalid subscription benefit';END IF;IF p_data->>'mode'='members' THEN IF (p_data->>'price_cents')::integer<>0 THEN RAISE EXCEPTION 'Members-only programs have no separate price';END IF;doc=jsonb_set(jsonb_set(doc,'{mode}','"native"'),'{price_cents}','50');END IF;PERFORM program_validate_v62(doc,p_trainer,p_allow_empty);END $$;
CREATE FUNCTION public.creator_program_access(p_user uuid,p_edition uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT (p_user=auth.uid() OR current_setting('role',true) NOT IN ('anon','authenticated')) AND p_user IS NOT NULL AND (has_role(p_user,'admin') OR EXISTS(SELECT 1 FROM program_editions e JOIN trainer_programs p ON p.id=e.program_id WHERE e.id=p_edition AND (p.trainer_id=p_user OR (NOT p.blocked AND e.review_status='approved' AND account_can_act(p_user,false) AND (EXISTS(SELECT 1 FROM program_enrollments n WHERE n.edition_id=e.id AND n.user_id=p_user AND n.state='active' AND (n.expires_at IS NULL OR n.expires_at>now())) OR (EXISTS(SELECT 1 FROM program_subscription_enrollments n WHERE n.edition_id=e.id AND n.user_id=p_user) AND (e.document->>'mode'='members' OR (e.document->>'mode'='native' AND e.document->'subscription_access'='true'::jsonb)) AND creator_has_access(p_user,p.trainer_id))))))) $$;
CREATE FUNCTION public.creator_program_deadline(p_user uuid,p_edition uuid) RETURNS timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT CASE WHEN has_role(p_user,'admin') OR p.trainer_id=p_user OR EXISTS(SELECT 1 FROM program_enrollments n WHERE n.edition_id=e.id AND n.user_id=p_user AND n.state='active' AND n.expires_at IS NULL) THEN NULL ELSE greatest((SELECT max(n.expires_at) FROM program_enrollments n WHERE n.edition_id=e.id AND n.user_id=p_user AND n.state='active'),(SELECT max(r.period_end) FROM creator_receipts r WHERE r.user_id=p_user AND r.trainer_id=p.trainer_id AND r.fulfillable AND NOT r.refund_pending AND r.refunded_cents=0 AND r.period_start<=now() AND r.period_end>now() AND NOT EXISTS(SELECT 1 FROM creator_disputes d WHERE d.order_id=r.id AND d.status IN ('open','lost')) AND EXISTS(SELECT 1 FROM program_subscription_enrollments n WHERE n.edition_id=e.id AND n.user_id=p_user))) END FROM program_editions e JOIN trainer_programs p ON p.id=e.program_id WHERE e.id=p_edition AND creator_program_access(p_user,p_edition) $$;
CREATE OR REPLACE FUNCTION public.program_access(p_edition uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT creator_program_access(auth.uid(),p_edition) $$;
CREATE OR REPLACE FUNCTION public.program_member(p_program uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM program_enrollments WHERE program_id=p_program AND user_id=auth.uid()) OR EXISTS(SELECT 1 FROM program_subscription_enrollments WHERE program_id=p_program AND user_id=auth.uid()) $$;
CREATE VIEW public.program_member_enrollments WITH(security_invoker=true) AS SELECT user_id,program_id,edition_id,source,state,verification_reference,starts_at,expires_at,created_at FROM program_enrollments WHERE user_id=auth.uid() UNION ALL SELECT n.user_id,n.program_id,n.edition_id,'subscription'::text,CASE WHEN program_access(n.edition_id) THEN 'active' ELSE 'revoked' END,NULL::text,n.created_at,creator_program_deadline(n.user_id,n.edition_id),n.created_at FROM program_subscription_enrollments n WHERE user_id=auth.uid() AND NOT EXISTS(SELECT 1 FROM program_enrollments p WHERE p.user_id=n.user_id AND p.edition_id=n.edition_id AND p.state='active' AND (p.expires_at IS NULL OR p.expires_at>now()));
GRANT SELECT ON public.program_member_enrollments TO authenticated;
ALTER FUNCTION public.enroll_fitness_program(uuid) RENAME TO enroll_fitness_program_v58;
CREATE FUNCTION public.enroll_fitness_program(p_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE e program_editions%ROWTYPE;t uuid;BEGIN SELECT edition.* INTO e FROM program_editions edition JOIN trainer_programs p ON p.current_edition=edition.id WHERE p.id=p_id AND p.published AND NOT p.blocked AND edition.review_status='approved';SELECT trainer_id INTO t FROM trainer_programs WHERE id=p_id;IF e.document->>'mode'='members' OR (e.document->>'mode'='native' AND e.document->'subscription_access'='true'::jsonb AND creator_has_access(auth.uid(),t)) THEN IF NOT creator_has_access(auth.uid(),t) OR NOT trainer_is_eligible(t,false) OR EXISTS(SELECT 1 FROM program_edition_videos x JOIN trainer_videos v ON v.id=x.video_id WHERE x.edition_id=e.id AND v.review_status<>'approved') OR EXISTS(SELECT 1 FROM program_edition_assets x JOIN program_assets a ON a.id=x.asset_id WHERE x.edition_id=e.id AND a.review_status<>'approved') THEN RAISE EXCEPTION 'Active subscription and approved content required';END IF;INSERT INTO program_subscription_enrollments(user_id,edition_id,program_id) VALUES(auth.uid(),e.id,p_id) ON CONFLICT DO NOTHING;RETURN e.id;END IF;RETURN enroll_fitness_program_v58(p_id);END $$;
CREATE FUNCTION public.program_subscription_benefit(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM trainer_programs p JOIN program_editions e ON e.id=p.current_edition WHERE p.id=p_id AND p.published AND NOT p.blocked AND e.review_status='approved' AND (e.document->>'mode'='members' OR (e.document->>'mode'='native' AND e.document->'subscription_access'='true'::jsonb)) AND creator_has_access(auth.uid(),p.trainer_id)) $$;
CREATE OR REPLACE FUNCTION public.program_media_access(p_user uuid,p_edition uuid,p_step uuid,p_variation uuid DEFAULT NULL) RETURNS TABLE(id uuid,path text,access_scope text,ads_allowed boolean,access_expires_at timestamptz,image_path text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT creator_program_access(p_user,p_edition) THEN RAISE EXCEPTION 'Program access denied'; END IF;
 RETURN QUERY SELECT v.id,v.path,v.access_scope,(e.document->>'mode'='free' AND v.access_scope='public'),creator_program_deadline(p_user,p_edition),img.object_path FROM program_editions e CROSS JOIN LATERAL jsonb_path_query(e.document,'$.weeks[*].days[*].workouts[*]') s CROSS JOIN LATERAL (SELECT (s->>'video_id')::uuid AS vid,NULL::uuid AS img WHERE p_variation IS NULL
 UNION ALL SELECT coalesce((var->>'video_id')::uuid,(s->>'video_id')::uuid),(var->>'image_id')::uuid FROM (SELECT value AS var FROM jsonb_path_query(s,'$.variations[*]') value UNION ALL SELECT value FROM jsonb_path_query(s,'$.exercises[*]') value UNION ALL SELECT value FROM jsonb_path_query(s,'$.exercises[*].variations[*]') value) options WHERE (var->>'id')::uuid=p_variation) choice JOIN trainer_videos v ON v.id=choice.vid LEFT JOIN program_images img ON img.id=choice.img AND img.review_status='approved'
 WHERE e.id=p_edition AND coalesce(s->>'id','')::uuid=p_step AND v.review_status='approved' AND (choice.img IS NULL OR img.id IS NOT NULL);
 IF NOT FOUND THEN RAISE EXCEPTION 'Approved workout unavailable'; END IF;
END $$;
CREATE OR REPLACE FUNCTION public.program_asset_access(p_user uuid,p_edition uuid,p_asset uuid) RETURNS TABLE(path text,deadline timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE e program_editions%ROWTYPE;p trainer_programs%ROWTYPE;
BEGIN
 SELECT * INTO e FROM program_editions WHERE id=p_edition;SELECT * INTO p FROM trainer_programs WHERE id=e.program_id;
 IF NOT EXISTS(SELECT 1 FROM program_edition_assets x JOIN program_assets a ON a.id=x.asset_id WHERE x.edition_id=p_edition AND a.id=p_asset AND a.review_status='approved') OR NOT creator_program_access(p_user,p_edition) THEN RAISE EXCEPTION 'Purchased file access denied';END IF;
 PERFORM pg_advisory_xact_lock(hashtext('download:'||p_user));IF (SELECT count(*) FROM program_download_events WHERE user_id=p_user AND created_at>now()-interval '1 minute')>=30 THEN RAISE EXCEPTION 'Download limit reached';END IF;
 INSERT INTO program_download_events(user_id,asset_id) VALUES(p_user,p_asset);
 RETURN QUERY SELECT a.path,creator_program_deadline(p_user,p_edition) FROM program_assets a WHERE a.id=p_asset;
END $$;
CREATE OR REPLACE FUNCTION public.set_program_progress(p_edition uuid,p_step uuid,p_completed boolean DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT (EXISTS(SELECT 1 FROM program_enrollments WHERE user_id=auth.uid() AND edition_id=p_edition) OR EXISTS(SELECT 1 FROM program_subscription_enrollments WHERE user_id=auth.uid() AND edition_id=p_edition)) OR NOT program_access(p_edition)
 OR NOT EXISTS(SELECT 1 FROM program_editions e CROSS JOIN LATERAL jsonb_path_query(e.document,'$.weeks[*].days[*].workouts[*].id') s WHERE e.id=p_edition AND (s #>> '{}')::uuid=p_step) THEN RAISE EXCEPTION 'Enrollment and valid workout required'; END IF;
 INSERT INTO program_progress(user_id,edition_id,step_id,completed) VALUES(auth.uid(),p_edition,p_step,coalesce(p_completed,false)) ON CONFLICT(user_id,edition_id,step_id) DO UPDATE SET completed=coalesce(p_completed,program_progress.completed),resumed_at=now();
END $$;
CREATE TABLE public.program_download_progress(user_id uuid NOT NULL REFERENCES auth.users(id),edition_id uuid NOT NULL REFERENCES public.program_editions(id),asset_id uuid NOT NULL REFERENCES public.program_assets(id),completed boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,edition_id,asset_id));
ALTER TABLE public.program_download_progress ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.program_download_progress FROM PUBLIC,anon,authenticated;GRANT ALL ON public.program_download_progress TO service_role;GRANT SELECT ON public.program_download_progress TO authenticated;
CREATE POLICY own_download_progress ON public.program_download_progress FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.complete_program_download(p_edition uuid,p_asset uuid,p_completed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NOT (EXISTS(SELECT 1 FROM program_enrollments WHERE user_id=auth.uid() AND edition_id=p_edition) OR EXISTS(SELECT 1 FROM program_subscription_enrollments WHERE user_id=auth.uid() AND edition_id=p_edition)) OR NOT program_access(p_edition) OR NOT EXISTS(SELECT 1 FROM program_edition_assets WHERE edition_id=p_edition AND asset_id=p_asset) THEN RAISE EXCEPTION 'Program enrollment required';END IF;INSERT INTO program_download_progress(user_id,edition_id,asset_id,completed) VALUES(auth.uid(),p_edition,p_asset,p_completed) ON CONFLICT(user_id,edition_id,asset_id) DO UPDATE SET completed=excluded.completed,updated_at=now();END $$;
REVOKE ALL ON FUNCTION public.creator_program_access(uuid,uuid),public.creator_program_deadline(uuid,uuid),public.program_validate_v62(jsonb,uuid,boolean),public.program_validate(jsonb,uuid,boolean),public.enroll_fitness_program_v58(uuid),public.enroll_fitness_program(uuid),public.program_subscription_benefit(uuid),public.complete_program_download(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.creator_program_access(uuid,uuid),public.creator_program_deadline(uuid,uuid) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.enroll_fitness_program(uuid),public.program_subscription_benefit(uuid),public.complete_program_download(uuid,uuid,boolean) TO authenticated;
CREATE FUNCTION public.guard_subscriber_program_purchase() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF EXISTS(SELECT 1 FROM program_editions e WHERE e.id=NEW.edition_id AND e.document->'subscription_access'='true'::jsonb) AND creator_has_access(NEW.user_id,NEW.trainer_id) THEN RAISE EXCEPTION 'Included with your subscription; enroll without a new purchase';END IF;RETURN NEW;END $$;
CREATE TRIGGER subscriber_program_purchase_guard BEFORE INSERT ON public.program_orders FOR EACH ROW EXECUTE FUNCTION public.guard_subscriber_program_purchase();
REVOKE ALL ON FUNCTION public.guard_subscriber_program_purchase() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.feedback_can_access(p_user uuid,p_video uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM trainer_videos v WHERE v.id=p_video AND v.review_status='approved' AND v.category !~* 'youth|homeschool|nutrition' AND (v.access_scope='public' OR creator_video_public(v.id) OR EXISTS(SELECT 1 FROM creator_video_access a WHERE a.video_id=v.id AND creator_has_access(p_user,a.trainer_id)) OR EXISTS(SELECT 1 FROM program_subscription_enrollments n JOIN program_edition_videos x ON x.edition_id=n.edition_id WHERE n.user_id=p_user AND x.video_id=v.id AND creator_program_access(p_user,n.edition_id)) OR EXISTS(SELECT 1 FROM program_edition_videos x JOIN program_editions e ON e.id=x.edition_id JOIN trainer_programs p ON p.id=e.program_id JOIN program_enrollments n ON n.edition_id=e.id WHERE x.video_id=v.id AND n.user_id=p_user AND n.state='active' AND (n.expires_at IS NULL OR n.expires_at>now()) AND e.review_status='approved' AND NOT p.blocked AND account_can_act(p_user,false))))
$$;
COMMIT;
